/*  Example: Character Codes
    Print some printable characters with their codes
    Author: Peter Brusilovsky
*/

#define FIRSTCHAR ' '
#define LASTCHAR 'z'
#include <stdio.h>
main () {
    char c = FIRSTCHAR;
    while(c <= LASTCHAR) {
        printf("%c = %d\n", c, (int) c);
        ++c;
    }
}
